selector_to_html = {"a[href=\"coverage/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">UT Coverage<a class=\"headerlink\" href=\"#ut-coverage\" title=\"Link to this heading\">#</a></h1><p>Unit test coverage reports generated by CI:</p>", "a[href=\"#test-reports\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Test Reports<a class=\"headerlink\" href=\"#test-reports\" title=\"Link to this heading\">#</a></h1>", "a[href=\"unit/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">UT Summary<a class=\"headerlink\" href=\"#ut-summary\" title=\"Link to this heading\">#</a></h1><p>Unit test summary reports generated by CI:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
